1	import React, { useState, useEffect } from 'react';
2	import { getRelatorio, getMinhaEmpresa, getCaixa, getCaixaHistorico, aprovarConferencia, getConfig } from '../../services/restauranteService';
3	import Icon from '../../components/AppIcon';
4	import CaixaAtualPanel from './CaixaAtualPanel';
5	import HistoricoCaixasPanel from './HistoricoCaixasPanel';
6	import RestauranteHeader from '../../components/restaurante/RestauranteHeader';
7	
8	const fmt      = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
9	const fmtDate  = (d) => d ? new Date(d).toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' }) : '—';
10	const today    = () => new Date().toISOString().slice(0, 10);
11	const thisMonth = () => new Date().toISOString().slice(0, 7);
12	const thisYear  = () => new Date().getFullYear().toString();
13	const startOf   = (d) => new Date(d + 'T00:00:00-03:00').toISOString();
14	const endOf     = (d) => new Date(d + 'T23:59:59-03:00').toISOString();
15	const lastDay   = (ym) => { const [y, m] = ym.split('-').map(Number); return new Date(y, m, 0).getDate(); };
16	const ANOS      = Array.from({ length: 4 }, (_, i) => String(new Date().getFullYear() - i));
17	const MODOS     = [{ value: 'dia', label: 'Dia' }, { value: 'mes', label: 'Mês' }, { value: 'ano', label: 'Ano' }, { value: 'periodo', label: 'Período' }];
18	const PAYMENT_LABELS = { pix: 'PIX', credit_card: 'Cartão Crédito', debit_card: 'Cartão Débito', cash: 'Dinheiro', taxa_cartao: '+ Taxa cartão' };
19	const PAYMENT_ICONS  = { pix: 'QrCode', credit_card: 'CreditCard', debit_card: 'CreditCard', cash: 'Banknote' };
20	const PAYMENT_COLORS = { pix: 'border-blue-200 dark:border-blue-800 bg-blue-50 dark:bg-blue-950/40 text-blue-800 dark:text-blue-400', credit_card: 'border-purple-200 dark:border-purple-800 bg-purple-50 dark:bg-purple-950/40 text-purple-800 dark:text-purple-400', debit_card: 'border-indigo-200 dark:border-indigo-800 bg-indigo-50 dark:bg-indigo-950/40 text-indigo-800 dark:text-indigo-400', cash: 'border-green-200 dark:border-green-800 bg-green-50 dark:bg-green-950/40 text-green-800 dark:text-green-400' };
21	const STATUS_LABELS  = { pending: 'Recebido', confirmed: 'Confirmado', preparing: 'Em Preparo', ready: 'Pronto', motoboy_collecting: 'Motoboy', out_for_delivery: 'Em Entrega', delivered: 'Entregue', canceled: 'Cancelado' };
22	const STATUS_COLORS  = { pending: 'bg-yellow-100 dark:bg-yellow-950/40 text-yellow-800 dark:text-yellow-400', confirmed: 'bg-blue-100 dark:bg-blue-950/40 text-blue-800 dark:text-blue-400', preparing: 'bg-orange-100 dark:bg-orange-950/40 text-orange-800 dark:text-orange-400', ready: 'bg-purple-100 dark:bg-purple-950/40 text-purple-800 dark:text-purple-400', motoboy_collecting: 'bg-sky-100 dark:bg-sky-950/40 text-sky-800 dark:text-sky-400', out_for_delivery: 'bg-indigo-100 dark:bg-indigo-950/40 text-indigo-800 dark:text-indigo-400', delivered: 'bg-green-100 dark:bg-green-950/40 text-green-800 dark:text-green-400', canceled: 'bg-red-100 dark:bg-red-950/40 text-red-800 dark:text-red-400' };
23	const ORIGEM_LABELS = { garcom: 'Garçom', estabelecimento: 'Caixa', delivery: 'Delivery' };
24	const CANAL_LABELS  = { delivery: 'Delivery', presencial: 'Salão', balcao: 'Balcão', marketplace: 'Marketplace' };
25	
26	const MEIO_LABELS = { dinheiro: 'Dinheiro', pix: 'PIX', transferencia: 'Transferência', cartao: 'Cartão' };
27	const PRINT_STYLE = `*{margin:0;padding:0;box-sizing:border-box}body{font-family:Arial,sans-serif;font-size:12px;padding:16px;max-width:800px;margin:0 auto}h1{font-size:18px;font-weight:900;margin-bottom:2px}h2{font-size:13px;font-weight:700;margin:14px 0 6px;border-bottom:1px solid #ddd;padding-bottom:4px}.sub{font-size:11px;color:#555;margin-bottom:12px}table{width:100%;border-collapse:collapse;margin-bottom:12px;font-size:11px}th{background:#f0f0f0;padding:6px 8px;text-align:left;font-weight:700;border:1px solid #ddd}td{padding:5px 8px;border:1px solid #ddd;vertical-align:top}.right{text-align:right}.bold{font-weight:700}.green{color:#166534}.red{color:#991b1b}.kpi-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:14px}.kpi{border:1px solid #ddd;border-radius:6px;padding:8px;text-align:center}.kpi .val{font-size:18px;font-weight:900;display:block;margin:2px 0}.kpi .lbl{font-size:10px;color:#555}footer{margin-top:16px;font-size:10px;color:#888;border-top:1px solid #ddd;padding-top:6px}@media print{button{display:none!important}}`;
28	const buildPrint = (dados, nome, label, caixa, taxaPagbank, historico, de, ate) => {
29	  const r = dados.resumo;
30	  const pedidos = dados.pedidos ?? [];
31	  const naoCancelados = pedidos.filter((p) => p.status !== 'canceled');
32	
33	  const pgto = Object.entries(r.por_pagamento ?? {}).map(([k, v]) => `<tr><td>${PAYMENT_LABELS[k] ?? k}</td><td class="right">${v.count}</td><td class="right bold green">${fmt(v.total)}</td></tr>`).join('');
34	
35	  const porCanal = naoCancelados.reduce((acc, p) => {
36	    const c = p.canal ?? 'outro';
37	    if (!acc[c]) acc[c] = { count: 0, total: 0 };
38	    acc[c].count++; acc[c].total += p.total ?? 0;
39	    return acc;
40	  }, {});
41	  const canalRows = Object.entries(porCanal).map(([k, v]) => `<tr><td>${CANAL_LABELS[k] ?? k}</td><td class="right">${v.count}</td><td class="right bold green">${fmt(v.total)}</td></tr>`).join('');
42	
43	  const saidasRows = (dados.saidas ?? []).map((s) => `<tr><td>${fmtDate(s.criado_em)}</td><td>${s.descricao}</td><td class="right bold red">- ${fmt(s.valor)}</td></tr>`).join('');
44	
45	  const fluxoRows = (dados.fluxo_caixa ?? []).map((f) => `<tr><td>${fmtDate(f.criado_em)}</td><td>#${f.order_id}</td><td>${PAYMENT_LABELS[f.forma_pagamento] ?? f.forma_pagamento}</td><td>${ORIGEM_LABELS[f.origem] ?? f.origem}</td><td class="right bold green">${fmt(f.valor)}</td><td class="right">${f.troco > 0 ? fmt(f.troco) : '—'}</td></tr>`).join('');
46	
47	  const pedidosRows = pedidos.slice().sort((a, b) => new Date(b.created_at) - new Date(a.created_at)).map((p) => {
48	    const itens = (p.itens ?? []).map((i) => `${i.quantity}x ${i.product_name}`).join(', ') || '—';
49	    return `<tr><td>#${p.id}</td><td>${fmtDate(p.created_at)}</td><td>${p.customers?.name ?? '—'}</td><td>${CANAL_LABELS[p.canal] ?? p.canal ?? '—'}</td><td class="${p.status === 'canceled' ? 'red' : 'green'}">${STATUS_LABELS[p.status] ?? p.status}</td><td>${itens}</td><td class="right bold">${fmt(p.total)}</td></tr>`;
50	  }).join('');
51	
52	  const caixaAberto = caixa?.aberto;
53	  const rc = caixaAberto ? (caixa.resumo ?? {}) : null;
54	  const porC = rc?.por_pagamento ?? {};
55	  const digitalCaixa = Object.entries(porC).filter(([k]) => k !== 'cash').reduce((s, [, v]) => s + v, 0);
56	  const taxaEstCaixa = taxaPagbank > 0 ? digitalCaixa * (taxaPagbank / 100) : 0;
57	  const sangriasRows = (caixa?.saidas ?? []).map((s) => `<tr><td>${fmtDate(s.criado_em)}</td><td>${MEIO_LABELS[s.meio] ?? s.meio ?? '—'}</td><td>${s.descricao}${s.tipo ? ` (${s.tipo})` : ''}</td><td class="right bold red">- ${fmt(s.valor)}</td></tr>`).join('');
58	  const adicoesRows = (caixa?.entradas ?? []).map((e) => `<tr><td>${fmtDate(e.criado_em)}</td><td>${MEIO_LABELS[e.meio] ?? e.meio ?? '—'}</td><td>${e.descricao}</td><td class="right bold green">+ ${fmt(e.valor)}</td></tr>`).join('');
59	
60	  const fechamentoCaixaHtml = caixaAberto ? `
61	<h2>Fechamento de Caixa — Sessão Atual</h2>
62	<div class="sub">Operador: ${caixa.nome_operador ?? '—'} · Aberto às: ${fmtDate(caixa.aberto_em)} · Fundo inicial: ${fmt(caixa.valor_inicial)}</div>
63	<div class="kpi-grid">
64	  <div class="kpi"><span class="val green">${fmt(rc.especie_calculada)}</span><span class="lbl">Espécie Esperada (Dinheiro)</span></div>
65	  <div class="kpi"><span class="val">${fmt(digitalCaixa)}</span><span class="lbl">Digital (PagBank)</span></div>
66	  <div class="kpi"><span class="val red">${fmt(taxaEstCaixa)}</span><span class="lbl">Taxa Estimada (${taxaPagbank}%)</span></div>
67	  <div class="kpi"><span class="val">${fmt((digitalCaixa - taxaEstCaixa))}</span><span class="lbl">Líquido Digital Esperado</span></div>
68	</div>
69	<table><tr><th></th><th class="right">Valor</th></tr>
70	<tr><td>Fundo Inicial</td><td class="right">${fmt(caixa.valor_inicial)}</td></tr>
71	<tr><td>+ Adições</td><td class="right bold green">+ ${fmt(rc.total_entradas)}</td></tr>
72	<tr><td>- Sangrias / Saídas</td><td class="right bold red">- ${fmt(rc.total_saidas)}</td></tr>
73	<tr><td class="bold">= Espécie Esperada em Caixa</td><td class="right bold">${fmt(rc.especie_calculada)}</td></tr>
74	</table>
75	<h2>Sangrias / Saídas do Caixa (${(caixa.saidas ?? []).length})</h2>
76	<table><tr><th>Hora</th><th>Meio</th><th>Descrição</th><th class="right">Valor</th></tr>${sangriasRows || '<tr><td colspan="4">Nenhuma sangria registrada.</td></tr>'}</table>
77	<h2>Adições ao Caixa (${(caixa.entradas ?? []).length})</h2>
78	<table><tr><th>Hora</th><th>Meio</th><th>Descrição</th><th class="right">Valor</th></tr>${adicoesRows || '<tr><td colspan="4">Nenhuma adição registrada.</td></tr>'}</table>
79	` : '';
80	
81	  const deD = de ? new Date(de) : null;
82	  const ateD = ate ? new Date(ate) : null;
83	  const fechadosPeriodo = (historico ?? []).filter((c) => {
84	    if (c.status !== 'fechado' || !c.fechado_em) return false;
85	    if (!deD || !ateD) return true;
86	    const f = new Date(c.fechado_em);
87	    return f >= deD && f <= ateD;
88	  });
89	  const fechadosRows = fechadosPeriodo.map((c) => {
90	    const cr = c.resumo ?? {};
91	    const dc = c.destinacao_fechamento ?? {};
92	    const dif = dc.diferenca ?? 0;
93	    const difClass = dif < 0 ? 'red' : dif > 0 ? '' : 'green';
94	    const conf = dc.conferencia_aprovada === true ? 'Aprovada' : dc.conferencia_aprovada === false ? 'Pendente' : '—';
95	    return `<tr><td>#${c.id} ${c.nome_operador}</td><td>${fmtDate(c.aberto_em)} → ${fmtDate(c.fechado_em)}</td><td class="right">${fmt(c.valor_inicial)}</td><td class="right">${fmt(cr.total_vendas)}</td><td class="right">${fmt(cr.saldo)}</td><td class="right">${dc.dinheiro_contado !== undefined ? fmt(dc.dinheiro_contado) : '—'}</td><td class="right bold ${difClass}">${dif !== 0 ? (dif > 0 ? '+' : '') + fmt(dif) : fmt(0)}</td><td>${conf}</td></tr>`;
96	  }).join('');
97	
98	  const historicoHtml = fechadosPeriodo.length > 0 || (historico && historico.length >= 0 && de && ate) ? `
99	<h2>Sessões de Caixa Fechadas no Período (${fechadosPeriodo.length})</h2>
100	<table><tr><th>Operador</th><th>Aberto → Fechado</th><th class="right">Fundo Inicial</th><th class="right">Vendas (Sistema)</th><th class="right">Saldo (Sistema)</th><th class="right">Contado</th><th class="right">Diferença</th><th>Conferência</th></tr>${fechadosRows || '<tr><td colspan="8">Nenhuma sessão fechada no período.</td></tr>'}</table>
101	` : '';
102	
103	  return `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Relatório Financeiro</title><style>${PRINT_STYLE}</style></head><body>
104	<h1>${nome ?? 'RESTAURANTE'}</h1>
105	<div class="sub">Relatório Financeiro Analítico — ${label}</div>
106	
107	${fechamentoCaixaHtml || '<h2>Fechamento de Caixa</h2><div class="sub">Nenhum caixa aberto no momento.</div>'}
108	${historicoHtml}
109	
110	<h2>Resumo Geral do Período</h2>
111	<div class="kpi-grid">
112	  <div class="kpi"><span class="val green">${fmt(r.total_vendas)}</span><span class="lbl">Faturamento</span></div>
113	  <div class="kpi"><span class="val red">- ${fmt(r.total_saidas)}</span><span class="lbl">Saídas</span></div>
114	  <div class="kpi"><span class="val">${fmt(r.saldo_liquido)}</span><span class="lbl">Saldo Líquido</span></div>
115	  <div class="kpi"><span class="val">${fmt(r.ticket_medio)}</span><span class="lbl">Ticket Médio</span></div>
116	</div>
117	<div class="kpi-grid">
118	  <div class="kpi"><span class="val">${r.total_pedidos}</span><span class="lbl">Total Pedidos</span></div>
119	  <div class="kpi"><span class="val green">${r.entregues}</span><span class="lbl">Finalizados</span></div>
120	  <div class="kpi"><span class="val">${r.em_andamento}</span><span class="lbl">Em Andamento</span></div>
121	  <div class="kpi"><span class="val red">${r.cancelados}</span><span class="lbl">Cancelados</span></div>
122	</div>
123	
124	<h2>Comissões e Gorjetas</h2>
125	<table><tr><th></th><th class="right">Gerado no Período</th><th class="right">Pago no Período</th></tr>
126	<tr><td>Comissão Garçom</td><td class="right">${fmt(r.total_comissao)}</td><td class="right bold">${fmt(r.total_comissoes_pagas)}</td></tr>
127	<tr><td>Gorjeta</td><td class="right">${fmt(r.total_gorjeta)}</td><td class="right bold">${fmt(r.total_gorjetas_pagas)}</td></tr>
128	<tr><td>Troco</td><td class="right" colspan="2">${fmt(r.total_troco)}</td></tr>
129	</table>
130	
131	<h2>Por Forma de Pagamento</h2>
132	<table><tr><th>Método</th><th class="right">Qtd</th><th class="right">Total</th></tr>${pgto || '<tr><td colspan="3">Sem dados no período.</td></tr>'}</table>
133	
134	<h2>Por Canal de Venda</h2>
135	<table><tr><th>Canal</th><th class="right">Pedidos</th><th class="right">Total</th></tr>${canalRows || '<tr><td colspan="3">Sem dados no período.</td></tr>'}</table>
136	
137	<h2>Saídas (${(dados.saidas ?? []).length})</h2>
138	<table><tr><th>Data</th><th>Descrição</th><th class="right">Valor</th></tr>${saidasRows || '<tr><td colspan="3">Nenhuma saída no período.</td></tr>'}</table>
139	
140	<h2>Fluxo de Caixa Detalhado (${(dados.fluxo_caixa ?? []).length})</h2>
141	<table><tr><th>Hora</th><th>Pedido</th><th>Forma</th><th>Origem</th><th class="right">Valor</th><th class="right">Troco</th></tr>${fluxoRows || '<tr><td colspan="6">Sem movimento no período.</td></tr>'}</table>
142	
143	<h2>Todos os Pedidos (${pedidos.length})</h2>
144	<table><tr><th>Pedido</th><th>Data/Hora</th><th>Cliente</th><th>Canal</th><th>Status</th><th>Itens</th><th class="right">Total</th></tr>${pedidosRows || '<tr><td colspan="7">Nenhum pedido no período.</td></tr>'}</table>
145	
146	<footer>Emitido em: ${new Date().toLocaleString('pt-BR')}</footer>
147	<script>window.print();setTimeout(()=>{try{window.frameElement.parentNode.removeChild(window.frameElement)}catch(e){}},2000)</script>
148	</body></html>`;
149	};
150	const printIframe = (html) => {
151	  const f = document.createElement('iframe');
152	  f.style.cssText = 'position:fixed;bottom:-1px;left:-1px;width:1px;height:1px;border:0;opacity:0;pointer-events:none';
153	  document.body.appendChild(f);
154	  try { f.contentDocument.open(); f.contentDocument.write(html); f.contentDocument.close(); }
155	  catch { f.remove(); const w = window.open('', '_blank'); if (w) { w.document.write(html); w.document.close(); } }
156	};
157	
