419	                            <p className="text-xs text-[#71717A] dark:text-[#A1A1AA]">{PAYMENT_LABELS[p.payment_method] ?? p.payment_method}</p>
420	                            <p className={`text-sm font-bold text-right ${p.status === 'canceled' ? 'text-red-400 line-through' : 'text-[#18181B] dark:text-[#F4F4F5]'}`}>{fmt(p.total)}</p>
421	                          </div>
422	                        ))}
423	                      </div>
424	                      <div className="px-5 py-3 bg-[#FAFAFA] dark:bg-[#18181B] border-t border-[#E4E4E7] dark:border-[#3F3F46] flex justify-between"><span className="text-sm text-[#71717A] dark:text-[#A1A1AA]">{dados.pedidos.length} pedidos · {r.cancelados} cancelados</span><span className="text-sm font-black text-green-700 dark:text-green-400">{fmt(r.total_vendas)} faturados</span></div>
425	                    </div>
426	                  )}
427	              </div>
428	            )}
429	          </>
430	        )}
431	
432	        {!dados && !loading && (
433	          <div className="bg-white dark:bg-[#27272A] rounded-2xl border border-[#E4E4E7] dark:border-[#3F3F46] p-10 text-center">
434	            <Icon name="BarChart2" size={32} className="text-[#D4D4D8] mx-auto mb-3" />
435	            <p className="text-[#71717A] dark:text-[#A1A1AA]">Selecione o período e clique em Buscar.</p>
436	          </div>
437	        )}
438	
439	        {/* Histórico de Caixas */}
440	        <HistoricoCaixasPanel historico={historico} />
441	
442	      </main>
443	    </div>
444	  );
445	};
